// ─── File: tests/upload.spec.ts ───
import { test, expect } from '@playwright/test';
import path from 'path';

test.describe('Document upload during onboarding', () => {

  // 1) Standard file input: setInputFiles with a single file path.
  test('single file via setInputFiles on the input', async ({ page }) => {
    await page.goto('/onboarding/documents');
    const input = page.getByLabel('Address proof');       // real <input type=file>
    await input.setInputFiles(path.join(__dirname, '../fixtures/address-proof.pdf'));

    // UI verification (auto-waiting)
    await expect(page.getByText('address-proof.pdf')).toBeVisible();
    // Server/content verification: it appears in the document list
    await expect(page.getByRole('listitem')
      .filter({ hasText: 'address-proof.pdf' })).toHaveCount(1);
  });

  // 2) In-memory buffer: generate a file on the fly, no fixture committed.
  test('single file from an in-memory buffer', async ({ page }) => {
    await page.goto('/onboarding/documents');
    const input = page.getByLabel('Income proof');
    await input.setInputFiles({
      name: 'salary-slip.pdf',
      mimeType: 'application/pdf',
      buffer: Buffer.from('%PDF-1.4 synthetic salary slip for SAV2001'),
    });
    await expect(page.getByText('salary-slip.pdf')).toBeVisible();
  });

  // 3) Multiple files: array of paths (input must have `multiple`).
  test('multiple files via setInputFiles array', async ({ page }) => {
    await page.goto('/onboarding/documents');
    const input = page.getByLabel('Identity documents');
    await input.setInputFiles([
      path.join(__dirname, '../fixtures/address-proof.pdf'),
      { name: 'pan.png', mimeType: 'image/png', buffer: Buffer.from('fake-png-bytes') },
    ]);
    // Verify BOTH files and the count
    await expect(page.getByText('address-proof.pdf')).toBeVisible();
    await expect(page.getByText('pan.png')).toBeVisible();
    await expect(page.getByRole('listitem')).toHaveCount(2);
  });

  // 4) Custom control that opens the OS dialog: capture the filechooser event.
  test('custom upload button via filechooser event', async ({ page }) => {
    await page.goto('/onboarding/documents');
    // Register the handler BEFORE the click that opens the dialog.
    const [chooser] = await Promise.all([
      page.waitForEvent('filechooser'),
      page.getByRole('button', { name: 'Upload passport' }).click(),
    ]);
    expect(chooser.isMultiple()).toBe(false);
    await chooser.setFiles(path.join(__dirname, '../fixtures/address-proof.pdf'));
    await expect(page.getByText('Upload complete')).toBeVisible();
  });

  // 5) Negative: disallowed type must be rejected with the right error.
  test('rejects a disallowed file type', async ({ page }) => {
    await page.goto('/onboarding/documents');
    const input = page.getByLabel('Address proof');
    await input.setInputFiles({
      name: 'malware.exe', mimeType: 'application/octet-stream',
      buffer: Buffer.from('MZ fake exe'),
    });
    await expect(page.getByRole('alert'))
      .toHaveText(/only pdf, png, or jpg files are allowed/i);
  });
});
